import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';
import { createInvoice, issueInvoice, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('exportCsv returns header for empty invoices', () => {
  const csv = exportCsv([]);
  assert.equal(csv, 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n');
});

test('exportCsv exports single invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');
  assert.equal(lines.length, 3); // header + 1 invoice + empty trailing
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
  assert.ok(lines[1].includes('INV-2026-0001'));
  assert.ok(lines[1].includes('Northwind Studio'));
  assert.ok(lines[1].includes('2026-09-01'));
  assert.ok(lines[1].includes('2026-10-01'));
  assert.ok(lines[1].includes('issued'));
});

test('exportCsv exports multiple invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-02',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const csv = exportCsv([issued1, issued2]);
  const lines = csv.split('\n');
  assert.equal(lines.length, 4); // header + 2 invoices + empty trailing
  assert.ok(lines[1].includes('INV-2026-0001'));
  assert.ok(lines[2].includes('INV-2026-0002'));
});

test('exportCsv formats amounts with 2 decimal places', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'STICKER', qty: 100 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');
  // Amounts should have exactly 2 decimal places
  assert.ok(/\d+\.\d{2}/.test(lines[1]));
});

test('exportCsv uses no currency sign', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');
  // Should not contain € or $
  assert.ok(!lines[1].includes('€'));
  assert.ok(!lines[1].includes('$'));
});

test('exportCsv uses no thousands separator', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-01',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');
  // Should not contain commas in the number fields (only as separators)
  const amounts = lines[1].split(',').slice(5); // Get last 5 fields (amounts)
  for (const amount of amounts) {
    // Remove quotes if present
    const unquoted = amount.replace(/"/g, '');
    // Should not have commas in the actual number (dots are OK)
    assert.ok(!unquoted.match(/\d,\d/), `Amount ${amount} has comma in number`);
  }
});

test('exportCsv escapes fields with commas', () => {
  const inv = createInvoice({
    customerId: 'C-006',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');
  // C-006 is "Marlow "The Print Shop"" which contains special characters
  assert.ok(lines[1].includes('"Marlow'));
});

test('exportCsv escapes fields with double quotes', () => {
  const inv = createInvoice({
    customerId: 'C-006',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');
  // Should have escaped quotes
  assert.ok(lines[1].includes('""'));
});

test('exportCsv includes invoice number', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');
  assert.ok(lines[1].startsWith('INV-2026-0001'));
});

test('exportCsv includes customer name', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');
  assert.ok(lines[1].includes('Northwind Studio'));
});

test('exportCsv includes issue date', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');
  assert.ok(lines[1].includes('2026-09-01'));
});

test('exportCsv includes due date', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');
  assert.ok(lines[1].includes('2026-10-01'));
});

test('exportCsv includes status', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');
  assert.ok(lines[1].includes('issued'));
});

test('exportCsv includes subtotal', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');
  // Subtotal for C-001 with DES-HOUR*5 = 42500 cents = 425.00
  assert.ok(lines[1].includes('425.00'));
});

test('exportCsv includes discount', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');
  // Discount for C-001 (gold tier, 5%) = 21.25
  assert.ok(lines[1].includes('21.25'));
});

test('exportCsv includes VAT', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');
  // VAT = 8479 cents = 84.79
  assert.ok(lines[1].includes('84.79'));
});

test('exportCsv includes total', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');
  // Total = 48854 cents = 488.54
  assert.ok(lines[1].includes('488.54'));
});

test('exportCsv includes due amount', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');
  // Due = 48854 cents = 488.54 (not paid yet)
  assert.ok(lines[1].includes('488.54'));
});

test('exportCsv shows due as 0 for paid invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const paid = recordPayment(issued, { amount: 48854, date: '2026-09-15' }).value;

  const csv = exportCsv([paid]);
  const lines = csv.split('\n');
  // Due should be 0.00 (fully paid)
  assert.ok(lines[1].endsWith('0.00\n'));
});

test('exportCsv shows partial due for partially paid invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const partial = recordPayment(issued, { amount: 20000, date: '2026-09-15' }).value;

  const csv = exportCsv([partial]);
  const lines = csv.split('\n');
  // Due should be 48854 - 20000 = 28854 cents = 288.54
  assert.ok(lines[1].includes('288.54'));
});

test('exportCsv with draft invoice shows empty number', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const csv = exportCsv([draft]);
  const lines = csv.split('\n');
  // First field (number) should be empty
  assert.ok(lines[1].startsWith(','));
});

test('exportCsv preserves invoice order', () => {
  const invs = [];
  for (let i = 0; i < 3; i++) {
    const inv = createInvoice({
      customerId: 'C-001',
      issueDate: `2026-09-0${i + 1}`,
      lines: [{ sku: 'DES-HOUR', qty: i + 1 }],
    }).value;
    const issued = issueInvoice(inv, invs.map(x => x.number || '')).value;
    invs.push(issued);
  }

  const csv = exportCsv(invs);
  const lines = csv.split('\n');
  // Check that invoices are in the original order
  assert.ok(lines[1].includes('INV-2026-0001'));
  assert.ok(lines[2].includes('INV-2026-0002'));
  assert.ok(lines[3].includes('INV-2026-0003'));
});

test('exportCsv ends lines with newline', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const csv = exportCsv([issued]);
  // Each line should end with \n
  assert.ok(csv.split('\n').every((line, i) => i === csv.split('\n').length - 1 || csv.includes(line + '\n')));
});

test('exportCsv with complex customer names', () => {
  const customers = ['C-001', 'C-003', 'C-006', 'C-012'];
  const invs = customers.map((customerId, i) => {
    const inv = createInvoice({
      customerId,
      issueDate: '2026-09-01',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;
    return issueInvoice(inv, invs.map(x => x.number || '')).value;
  });

  const csv = exportCsv(invs);
  const lines = csv.split('\n');
  assert.ok(lines[1].includes('Northwind Studio'));
  assert.ok(lines[2].includes('Kite'));
  assert.ok(lines[3].includes('Marlow'));
  assert.ok(lines[4].includes('Northwind Studio B.V.'));
});

test('exportCsv with invoices with vouchers', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const withVoucher = applyVoucher(inv, { code: 'PROMO', amount: 5000 }).value;
  const issued = issueInvoice(withVoucher, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');
  // Total should be 48854 - 5000 = 43854 cents = 438.54
  assert.ok(lines[1].includes('438.54'));
});

test('exportCsv with complex invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
      { sku: 'PRINT-A4', qty: 100 },
    ],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');
  assert.equal(lines.length, 3); // header + 1 invoice + empty trailing
  assert.ok(lines[1].includes('INV-2026-0001'));
});

test('exportCsv with various customer tiers', () => {
  const customers = [
    { id: 'C-001', tier: 'gold', name: 'Northwind Studio' },
    { id: 'C-003', tier: 'silver', name: 'Kite & Co' },
    { id: 'C-002', tier: 'standard', name: 'Blue Fern Bakery' },
  ];

  const invs = customers.map((c, i) => {
    const inv = createInvoice({
      customerId: c.id,
      issueDate: '2026-09-01',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    }).value;
    return issueInvoice(inv, invs.map(x => x.number || '')).value;
  });

  const csv = exportCsv(invs);
  const lines = csv.split('\n');
  assert.equal(lines.length, 5); // header + 3 invoices + empty trailing
  assert.ok(lines[1].includes('Northwind Studio'));
  assert.ok(lines[2].includes('Kite'));
  assert.ok(lines[3].includes('Blue Fern'));
});

test('exportCsv with multiple payments', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const partial1 = recordPayment(issued, { amount: 15000, date: '2026-09-15' }).value;
  const partial2 = recordPayment(partial1, { amount: 15000, date: '2026-09-20' }).value;

  const csv = exportCsv([partial2]);
  const lines = csv.split('\n');
  // Due should be 48854 - 30000 = 18854 cents = 188.54
  assert.ok(lines[1].includes('188.54'));
});

test('exportCsv produces valid CSV format', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');

  // Header should have correct number of fields
  const headerFields = lines[0].split(',');
  assert.equal(headerFields.length, 10);

  // Data line should have same number of fields (accounting for quotes)
  const dataLine = lines[1];
  // Count unescaped commas
  let fieldCount = 1;
  let inQuotes = false;
  for (const char of dataLine) {
    if (char === '"') inQuotes = !inQuotes;
    if (char === ',' && !inQuotes) fieldCount++;
  }
  assert.equal(fieldCount, 10);
});

test('exportCsv with empty invoice number', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const csv = exportCsv([draft]);
  const lines = csv.split('\n');
  // Should start with comma (empty number field)
  assert.equal(lines[1][0], ',');
});

test('exportCsv does not mutate invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const originalStatus = issued.status;
  const originalNumber = issued.number;

  exportCsv([issued]);
  assert.equal(issued.status, originalStatus);
  assert.equal(issued.number, originalNumber);
});

